import { useEffect } from "react";
import { Navigate, useNavigate } from "react-router-dom";
import { Clock, LogOut, RefreshCw, X } from "lucide-react";
import { useAuth } from "@/context/AuthContext";

export default function PendingPage() {
  const { user, logout, refreshMe } = useAuth();
  const nav = useNavigate();

  useEffect(() => {
    const t = setInterval(() => {
      refreshMe();
    }, 10000);
    return () => clearInterval(t);
  }, [refreshMe]);

  if (!user) return <Navigate to="/login" replace />;
  if (user.role === "owner" || user.status === "approved")
    return <Navigate to="/" replace />;

  const rejected = user.status === "rejected";

  return (
    <div className="min-h-screen bg-[#fff7f0] grid place-items-center px-6">
      <div
        data-testid="pending-page"
        className="max-w-md w-full bg-white border border-[#efe3d6] rounded-3xl p-8 text-center shadow-[0_20px_60px_-30px_rgba(255,106,0,0.35)]"
      >
        <div
          className={`w-14 h-14 mx-auto rounded-2xl grid place-items-center ${
            rejected ? "bg-red-50 text-red-500" : "bg-[#ffe4d1] text-[#ff6a00]"
          }`}
        >
          {rejected ? <X size={24} /> : <Clock size={24} />}
        </div>
        <h1 className="mt-5 font-display text-2xl sm:text-3xl font-extrabold tracking-tight">
          {rejected ? "Access denied" : "Waiting for approval"}
        </h1>
        <p className="mt-2 text-[#5c534d]">
          {rejected ? (
            <>Your account was not approved by the owner. If you think this is a
              mistake, contact CarterB.</>
          ) : (
            <>
              Hey <span className="font-semibold text-[#1a1613]">@{user.username}</span>,
              your account is pending. Once <span className="font-semibold text-[#ff6a00]">CarterB</span> approves it,
              the games and chat unlock automatically.
            </>
          )}
        </p>
        <div className="mt-6 flex items-center justify-center gap-2">
          <button
            onClick={refreshMe}
            data-testid="pending-refresh"
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-full bg-[#ff6a00] text-white text-sm font-semibold hover:bg-[#e85d00] transition-colors"
          >
            <RefreshCw size={14} /> Check status
          </button>
          <button
            onClick={() => {
              logout();
              nav("/login");
            }}
            data-testid="pending-logout"
            className="inline-flex items-center gap-1.5 px-4 py-2 rounded-full border border-[#efe3d6] hover:border-[#ff6a00] hover:text-[#ff6a00] text-sm font-semibold transition-colors"
          >
            <LogOut size={14} /> Sign out
          </button>
        </div>
      </div>
    </div>
  );
}
